def total_cents(self, order_ids: Iterable[str]) -> int:
    """汇总给定订单的金额，返回整数分。

    已取消订单不计入（ORDER-REQ-008）。
    """
    total = 0.0
    for order_id in order_ids:
        order = self.repository.get(order_id)
        if order.status == "cancelled":
            continue
        total += float(order.amount)
    return int(total * 100)

def refund(self, order_id: str) -> Order:
    """整单退款。仅 paid / shipped 可退，退款后置为 cancelled。"""
    order = self.repository.get(order_id)
    if order.status == "cancelled":
        raise ValueError(f"order already cancelled: {order_id}")
    if order.status == "created":
        raise ValueError(f"unpaid order cannot be refunded: {order_id}")
    refunded = replace(order, status="cancelled")
    self.repository.save(refunded)
    return refunded

class OrderService:
    def __init__(self, repository: OrderRepository) -> None:
        self.repository = repository

    # ------------------------------------------------------------------ 查询
    def list_orders(
        self,
        customer_id: Optional[str] = None,
        status: Optional[str] = None,
        min_amount: Optional[Decimal] = None,
    ) -> List[Order]:
        """按条件列出订单。

        customer_id: 精确匹配客户。
        status:      订单状态筛选，尚未实现（ORDER-REQ-004）。
        min_amount:  金额下限筛选，尚未实现（ORDER-REQ-005）。
        """
        orders: Sequence[Order] = self.repository.all()
        if customer_id is not None:
            orders = [order for order in orders if order.customer_id == customer_id]
        return list(orders)

    def get_order(self, order_id: str) -> Order:
        return self.repository.get(order_id)

    # ------------------------------------------------------------------ 金额
    def total_cents(self, order_ids: Iterable[str]) -> int:
        """汇总给定订单的金额，返回整数分。

        已取消订单不计入（ORDER-REQ-008）。
        """
        total = 0.0
        for order_id in order_ids:
            order = self.repository.get(order_id)
            if order.status == "cancelled":
                continue
            total += float(order.amount)
        return int(total * 100)

    # ------------------------------------------------------------------ 退款
    def refund(self, order_id: str) -> Order:
        """整单退款。仅 paid / shipped 可退，退款后置为 cancelled。"""
        order = self.repository.get(order_id)
        if order.status == "cancelled":
            raise ValueError(f"order already cancelled: {order_id}")
        if order.status == "created":
            raise ValueError(f"unpaid order cannot be refunded: {order_id}")
        refunded = replace(order, status="cancelled")
        self.repository.save(refunded)
        return refunded

class OrderRepository:
    """内存实现，接口形状与生产环境的 DB 仓储保持一致。"""

    def __init__(self) -> None:
        self._orders: Dict[str, Order] = {}
        self.reset()

    def reset(self) -> None:
        self._orders = {
            oid: Order(
                order_id=oid,
                customer_id=cid,
                status=status,
                amount=Decimal(amount),
                created_at=created_at,
            )
            for oid, cid, status, amount, created_at in _SEED
        }

    def all(self) -> List[Order]:
        # 保持插入顺序，列表接口的行为依赖这一点
        return list(self._orders.values())

    def get(self, order_id: str) -> Order:
        try:
            return self._orders[order_id]
        except KeyError as exc:
            raise KeyError(f"order not found: {order_id}") from exc

    def save(self, order: Order) -> None:
        self._orders[order.order_id] = order

    def extend(self, orders: Iterable[Order]) -> None:
        for order in orders:
            self.save(order)

