def test_total_cents_no_truncation_odd_cents(service):
    """ORDER-REQ-007：0.01 + 1.13 必须精确等于 114 分。"""
    assert service.total_cents(["O1002", "O1007"]) == 114

def test_total_cents_no_truncation_small_amounts(service):
    """ORDER-REQ-007：0.01 + 2.00 必须精确等于 201 分。"""
    assert service.total_cents(["O1002", "O1006"]) == 201

def test_filter_by_min_amount_inclusive(service):
    """ORDER-REQ-005：min_amount 为闭区间下界（>=）。"""
    orders = service.list_orders(min_amount=Decimal("128.50"))
    assert _ids(orders) == {"O1003", "O1004", "O1008"}

def test_filter_by_status_multi(service):
    """ORDER-REQ-004：status 支持逗号分隔多值。"""
    orders = service.list_orders(status="created,cancelled")
    assert _ids(orders) == {"O1002", "O1005", "O1006"}

def test_filter_by_status_single(service):
    """ORDER-REQ-004：status 单值过滤，只返回该状态的订单。"""
    orders = service.list_orders(status="paid")
    assert _ids(orders) == {"O1001", "O1004", "O1007", "O1008"}
    assert all(order.status == "paid" for order in orders)

def test_filter_combines_customer_and_status(service):
    """ORDER-REQ-004/001：条件之间取交集。"""
    orders = service.list_orders(customer_id="C001", status="paid")
    assert _ids(orders) == {"O1001", "O1008"}

def test_filter_by_customer(service):
    """ORDER-REQ-002：按客户过滤。"""
    orders = service.list_orders(customer_id="C002")
    assert {order.order_id for order in orders} == {"O1004", "O1005"}

def test_list_all_returns_every_order(service):
    """ORDER-REQ-001：无条件查询返回全部订单且保持插入顺序。"""
    orders = service.list_orders()
    assert [order.order_id for order in orders] == [
        "O1001", "O1002", "O1003", "O1004", "O1005", "O1006", "O1007", "O1008",
    ]

def test_total_cents_empty_orders(service):
    """ORDER-REQ-007 边界：空列表合计为 0。"""
    assert service.total_cents([]) == 0

def test_total_cents_excludes_cancelled(service):
    """ORDER-REQ-008：已取消订单不计入合计。"""
    assert service.total_cents(["O1004", "O1005"]) == 30000

def test_total_cents_large_amounts(service):
    """ORDER-REQ-007 回归：128.50 + 300.00 + 1000.00 精确等于 142850 分。"""
    assert service.total_cents(["O1003", "O1004", "O1008"]) == 142850

def test_total_cents_round_amounts_still_exact(service):
    """ORDER-REQ-007 回归：19.99 + 0.01 精确等于 2000 分。"""
    assert service.total_cents(["O1001", "O1002"]) == 2000
